// Build the WhatsApp message body for each agent.
// We need the auction context from the earlier merge AND the agent from this step.
// In n8n, earlier-step data is accessed via $('Node Name').first().

const auctionCtx = $('Merge Auction + Lead Context').first().json;
const agents = $input.all();

return agents.map(item => {
  const agent = item.json;
  const body = [
    `🏠 Nuevo lead para ${auctionCtx.property_title}`,
    `💰 ${auctionCtx.property_price}`,
    `👤 Lead: ${auctionCtx.lead_name || 'Sin nombre'}`,
    ``,
    `Responde *TOMO-${auctionCtx.short_code}* para asignártelo.`,
    `(Expira en 5 min)`
  ].join('\n');

  return {
    json: {
      agent_id: agent.agent_id,
      agent_name: agent.name,
      to_phone: `whatsapp:${agent.whatsapp_number}`,
      body,
      auction_id: auctionCtx.auction_id,
      short_code: auctionCtx.short_code,
      conversation_id: auctionCtx.conversation_id
    }
  };
});

// Aggregate results for return value.
// We want to record on the auction row which agents were actually notified.
const items = $input.all();
const notifiedAgents = items
  .filter(i => i.json.agent_id)
  .map(i => i.json.agent_id);

return [{
  json: {
    auction_id: items[0]?.json?.auction_id,
    conversation_id: items[0]?.json?.conversation_id,
    short_code: items[0]?.json?.short_code,
    notified_agents: notifiedAgents,
    notified_count: notifiedAgents.length
  }
}];

parameters.query:
UPDATE auctions
SET notified_agents = $1::text[]
WHERE auction_id = $2::uuid;
